import{_ as t,o,c as a,ag as n}from"./chunks/framework.BIas3y6W.js";const u=JSON.parse('{"title":"Week 11 Homework — Finish the first feature, complete the spec, deploy","description":"","frontmatter":{"source":"weeks/11-agents/homework.md"},"headers":[],"relativePath":"weeks/11-agents/homework.md","filePath":"weeks/11-agents/homework.md"}'),r={name:"weeks/11-agents/homework.md"};function i(s,e,d,h,l,c){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="week-11-homework--finish-the-first-feature-complete-the-spec-deploy" tabindex="-1">Week 11 Homework — Finish the first feature, complete the spec, deploy <a class="header-anchor" href="#week-11-homework--finish-the-first-feature-complete-the-spec-deploy" aria-label="Permalink to &quot;Week 11 Homework — Finish the first feature, complete the spec, deploy&quot;">​</a></h1><blockquote><p><strong>Core:</strong> about 5 hours, required, including project time. <strong>Stretch:</strong> optional. <strong>Due before next week&#39;s Studio A</strong> (default 11:59 pm the night before). One small piece, AC1 in <code>SPEC.md</code> (<a href="./lab.html#part-a3--your-first-criterion-in-specmd-10-min">lab Part A3</a>), is due before this week&#39;s Studio B.</p></blockquote><p><strong>AI-use key:</strong> 🟢 AI on: use AI, following the <a href="./../../resources/safe-loop.html">Safe Loop</a>; agents always with approvals on · 🟡 AI limited: only in the way the task says · 🔴 AI off: close AI chat and turn off completions. <strong>Never</strong> paste a key or the contents of <code>.env</code> into any AI tool.</p><h2 id="deliverables-checklist" tabindex="-1">Deliverables checklist <a class="header-anchor" href="#deliverables-checklist" aria-label="Permalink to &quot;Deliverables checklist&quot;">​</a></h2><p>Submit on Canvas, the course&#39;s learning management system: your repository URL, the link to your <code>feature/ac1</code> branch, and your <strong>production URL</strong>. Your reflection is a separate Canvas item.</p><ul><li>☐ Before Studio B: AC1 and its edge case in <code>SPEC.md</code></li><li>☐ First feature finished on <code>feature/ac1</code>: a test that failed first, <code>npm test</code> green, a teach-back, an <code>Assisted-by:</code> line; the branch published to GitHub and <strong>not merged</strong> (<a href="#1-finish-your-first-feature-about-1-h">task 1</a>)</li><li>☐ A trace of your agent&#39;s run in <code>PROMPTS.md</code> (<a href="#2-trace-your-agents-run-about-30-min">task 2</a>)</li><li>☐ <code>SPEC.md</code> complete, with a build order (<a href="#3-complete-specmd-about-2-h">task 3</a>)</li><li>☐ Capstone deployed; production URL at the top of <code>README.md</code> (<a href="#4-deploy-on-day-one-about-30-min">task 4</a>)</li><li>☐ <code>PROMPTS.md</code>: an entry for each agent session, a teach-back before each agent commit, the Ownership statement updated (<a href="#5-the-agent-log-in-promptsmd-about-30-min">task 5</a>)</li><li>☐ Reflection on Canvas (🔴 AI off) (<a href="#6-reflection-a-moment-the-agent-surprised-me-about-30-min">task 6</a>)</li><li>☐ Everything committed and synced; Codespaces stopped</li></ul><table tabindex="0"><thead><tr><th>#</th><th>Task</th><th>AI use</th><th>About</th></tr></thead><tbody><tr><td>1</td><td>Finish your first feature</td><td>🟢 AI on for the agent, 🔴 AI off for the teach-back</td><td>1 h</td></tr><tr><td>2</td><td>Trace your agent&#39;s run</td><td>🔴 AI off</td><td>30 min</td></tr><tr><td>3</td><td>Complete <code>SPEC.md</code></td><td>🟡 AI limited</td><td>2 h</td></tr><tr><td>4</td><td>Deploy on day one</td><td>🟢 AI on (not needed)</td><td>30 min</td></tr><tr><td>5</td><td>The agent log in <code>PROMPTS.md</code></td><td>🔴 AI off for teach-backs</td><td>30 min</td></tr><tr><td>6</td><td>Reflection</td><td>🔴 AI off</td><td>30 min</td></tr><tr><td></td><td><strong>Total</strong></td><td></td><td><strong>about 5 h</strong></td></tr></tbody></table><h2 id="core-required" tabindex="-1">Core (required) <a class="header-anchor" href="#core-required" aria-label="Permalink to &quot;Core (required)&quot;">​</a></h2><h3 id="1-finish-your-first-feature-about-1-h" tabindex="-1">1. Finish your first feature (about 1 h) <a class="header-anchor" href="#1-finish-your-first-feature-about-1-h" aria-label="Permalink to &quot;1. Finish your first feature (about 1 h)&quot;">​</a></h3><p>🟢 <strong>AI on:</strong> agent mode with approvals on. 🔴 <strong>AI off</strong> for the teach-back.</p><p>Pick up <a href="./lab.html#part-b1--your-first-agent-built-feature-50-min">lab Part B1</a> wherever you stopped, on <code>feature/ac1</code>. Every step still counts: the failing test committed first, a <strong>new</strong> chat for the code, plan first, green in your own terminal with nothing changed in <code>tests/</code>, the diff read, the feature tried by hand, the teach-back, the commit with <code>Assisted-by:</code>, and <strong>Publish Branch</strong>. Don&#39;t merge it: week 12 Studio A turns it into your first pull request. If the agent fails twice at the same problem, apply the two-strikes rule: back to your last good commit, a fresh session, a better prompt.</p><h3 id="2-trace-your-agents-run-about-30-min" tabindex="-1">2. Trace your agent&#39;s run (about 30 min) <a class="header-anchor" href="#2-trace-your-agents-run-about-30-min" aria-label="Permalink to &quot;2. Trace your agent&#39;s run (about 30 min)&quot;">​</a></h3><p>🔴 <strong>AI off.</strong></p><p>In Be the Agent you logged every tool call by hand. A real agent made the same kind of calls for your first feature, in seconds. Open the chat session that built it (Copilot Chat keeps your past sessions in a list at the top of the chat panel; menus move, so if you can&#39;t find it, ask Copilot where chat history is) and expand its steps. In <code>PROMPTS.md</code>, under your feature&#39;s entry, fill in a call log:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">#### Trace of the build session</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| # | Tool call (read, search, edit, run…) | What it learned or changed | Did I approve it? |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|---|---|---|---|</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| 1 | [e.g. read AGENTS.md] | [e.g. the Scope and &quot;plan first&quot;] | [automatic / yes / skipped] |</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Calls in total:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">n</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] · </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Wasted calls:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [which, and why] · </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Compared with my Be the Agent log:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [one or two sentences]</span></span></code></pre></div><p>If your tool hides some steps, log what it shows and say so. Which call would you have made differently as the Model?</p><h3 id="3-complete-specmd-about-2-h" tabindex="-1">3. Complete <code>SPEC.md</code> (about 2 h) <a class="header-anchor" href="#3-complete-specmd-about-2-h" aria-label="Permalink to &quot;3. Complete \`SPEC.md\` (about 2 h)&quot;">​</a></h3><p>🟡 <strong>AI limited:</strong> you write the spec. An AI may critique it, but every change is yours. Next week a fresh chat reads it in the Goldfish test, so write it for a reader who knows nothing about your project.</p><ol><li><strong>Complete the spec (75 min).</strong> Fill in every section of <code>SPEC.md</code> from your pitch and your instructor&#39;s reply: problem, user, user stories (MUST, SHOULD, COULD), at least <strong>six</strong> acceptance criteria in WHEN … THE APP SHALL … form (including at least <strong>two edge cases</strong> and at least <strong>one for each feature type</strong> you chose), at least three things that are out of scope, the wireframe, and section 8, the capstone requirements you&#39;ll meet. It&#39;s the same format as week 5 (<a href="./../05-spec-first/example-spec.html">example spec</a>).</li><li><strong>Critique (15 min, optional).</strong> Ask Copilot in <strong>Ask</strong> mode: &quot;Read SPEC.md. Which acceptance criteria are too vague to test? List at most 5 problems. Don&#39;t rewrite anything.&quot; Decide yourself what to change.</li><li><strong>Build order (15 min).</strong> Below your criteria, number your MUST criteria in the order you&#39;ll build them. Each one should be one agent session: one criterion, the files it touches, and the test that checks it. If a criterion needs more than one session, split it. Small tasks also cost fewer credits.</li><li><strong>Commit</strong> on your feature branch (<code>git switch feature/ac1</code> first): <code>Complete SPEC with build order</code>. Until next week&#39;s pull request joins it to <code>main</code>, keep all your capstone commits on <code>feature/ac1</code>, so nothing conflicts.</li></ol><h3 id="4-deploy-on-day-one-about-30-min" tabindex="-1">4. Deploy on day one (about 30 min) <a class="header-anchor" href="#4-deploy-on-day-one-about-30-min" aria-label="Permalink to &quot;4. Deploy on day one (about 30 min)&quot;">​</a></h3><p>Deploy your capstone to Vercel <strong>now</strong>, as you did your micro-app in week 10, even if <code>main</code> is mostly the starter shell. Every later merge into <code>main</code> then redeploys it, and you find deployment problems now, not the night before the capstone is due.</p><ol><li>On <a href="https://vercel.com" target="_blank" rel="noreferrer">vercel.com</a>: <strong>Add New…</strong> → <strong>Project</strong> → <strong>Import</strong> your capstone repository. Leave the preset as <strong>Other</strong>.</li><li>If you use the AI example or any other secret key, add the environment variables before you click <strong>Deploy</strong> (and <strong>Redeploy</strong> after any later change). Details: &quot;Deploy on day one&quot; in your starter&#39;s <code>README.md</code>.</li><li>Open the <strong>production URL</strong> (the <code>.vercel.app</code> address under <strong>Domains</strong>), check it works, and put the URL at the top of your <code>README.md</code>. Commit it on <code>feature/ac1</code>; it reaches <code>main</code> through next week&#39;s pull request. (Vercel deploys <code>main</code>, so the live site shows the starter shell until then. That&#39;s fine.)</li><li>Submit the URL on Canvas. Next week you add a screenshot for Milestone 1.</li></ol><h3 id="5-the-agent-log-in-promptsmd-about-30-min" tabindex="-1">5. The agent log in <code>PROMPTS.md</code> (about 30 min) <a class="header-anchor" href="#5-the-agent-log-in-promptsmd-about-30-min" aria-label="Permalink to &quot;5. The agent log in \`PROMPTS.md\` (about 30 min)&quot;">​</a></h3><p>One entry per agent session, using the fields in your <code>PROMPTS.md</code>: the prompts (the check-first test has its own), the plan and what you changed in it, what happened, the red and green evidence, and what you checked or fixed yourself. A <strong>teach-back</strong> before each agent commit (🔴 AI off, 2–3 sentences in your own words; <a href="./../../resources/safe-loop.html#teach-back">how</a>). Update the <strong>Ownership statement</strong>: what you wrote, decided and changed yourself. Never paste keys or <code>.env</code> contents here; it&#39;s public.</p><h3 id="6-reflection-a-moment-the-agent-surprised-me-about-30-min" tabindex="-1">6. Reflection: &quot;a moment the agent surprised me&quot; (about 30 min) <a class="header-anchor" href="#6-reflection-a-moment-the-agent-surprised-me-about-30-min" aria-label="Permalink to &quot;6. Reflection: &quot;a moment the agent surprised me&quot; (about 30 min)&quot;">​</a></h3><p>🔴 <strong>AI off.</strong> Use the <a href="./../../templates/REFLECTION.html">reflection template</a> and submit it <strong>on Canvas</strong> (not in your repository: reflections are personal and graded). In section 1, describe one specific moment this week when an agent (or you, as the Model in Be the Agent) did something you didn&#39;t expect: what happened, what you saw in the output or the diff (quote the command, the error or the line), and what you did next. Then answer in two or three sentences: if your agent had ignored your <code>AGENTS.md</code> this week, what would actually have stopped it?</p><h2 id="stretch-optional" tabindex="-1">Stretch (optional) <a class="header-anchor" href="#stretch-optional" aria-label="Permalink to &quot;Stretch (optional)&quot;">​</a></h2><h3 id="read-a-minimal-agent-loop" tabindex="-1">Read a minimal agent loop <a class="header-anchor" href="#read-a-minimal-agent-loop" aria-label="Permalink to &quot;Read a minimal agent loop&quot;">​</a></h3><p>If you didn&#39;t reach it in class, do <a href="./lab.html#part-b3--read-a-minimal-agent-loop-15-min">lab Part B3</a>: about 50 lines of JavaScript that make a working agent. Annotate where the model, the tools and the approval check are, and answer its seven questions in <code>PROMPTS.md</code>. Reading only: don&#39;t run it.</p><h3 id="try-the-copilot-cli" tabindex="-1">Try the Copilot CLI <a class="header-anchor" href="#try-the-copilot-cli" aria-label="Permalink to &quot;Try the Copilot CLI&quot;">​</a></h3><p><a href="./lab.html#part-b2--try-the-copilot-cli-10-min">Lab Part B2</a> on one tiny task, approvals on. Note in <code>PROMPTS.md</code> how it compared with agent mode in the editor: number of steps, whether it planned first, and whether it ran the tests.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Minimum to keep up.</strong> Your first feature, with a test written before the code, is on the <code>feature/ac1</code> branch on GitHub, and your <code>AGENTS.md</code> has a Scope section. Week 12 Studio A merges that branch through your first pull request. If you&#39;re behind, tell your instructor early in the week.</p></div>`,32)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
